import{_ as a,o as e,c as r,ag as o}from"./chunks/framework.DMXcdKmJ.js";const c=JSON.parse('{"title":"使用数据点配置计算单元","description":"绑定已有数据点、编写计算逻辑、配置输出与触发，区分保存、试运行、启用和正式运行。","frontmatter":{"title":"使用数据点配置计算单元","description":"绑定已有数据点、编写计算逻辑、配置输出与触发，区分保存、试运行、启用和正式运行。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/guide/compute-datapoints.md","filePath":"zh/使用指南/使用数据点配置计算单元.md"}'),d={name:"zh/guide/compute-datapoints.md"};function n(i,t,s,h,p,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="使用数据点配置计算单元" tabindex="-1">使用数据点配置计算单元 <a class="header-anchor" href="#使用数据点配置计算单元" aria-label="Permalink to &quot;使用数据点配置计算单元&quot;">​</a></h1><p>入口：<strong>数据中心 → 计算单元</strong>。使用有工程配置权限的组织账号，先准备已确认路径、类型、质量和用途的数据点。</p><p>AI 已创建单元时，先按名称搜索并打开，检查现有输入和输出，不重复创建。</p><h2 id="_1-创建并找到单元" tabindex="-1">1. 创建并找到单元 <a class="header-anchor" href="#_1-创建并找到单元" aria-label="Permalink to &quot;1. 创建并找到单元&quot;">​</a></h2><p>点击 <strong>“新建单元”</strong>，填写名称，选择 JavaScript 或 Python，按需要选择分组和描述，再点击 <strong>“创建”</strong>。</p><p>名称用于查找，实际输出路径还关联单元标识和输出 Key。改显示名不会自动换路径；修改标识或输出 Key 前先检查页面、报警和其他计算的引用。</p><h2 id="_2-分清参数和数据点变量" tabindex="-1">2. 分清参数和数据点变量 <a class="header-anchor" href="#_2-分清参数和数据点变量" aria-label="Permalink to &quot;2. 分清参数和数据点变量&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>用途</th></tr></thead><tbody><tr><td>参数</td><td>调用脚本时传入的参数定义及调试输入，不是设备采样值</td></tr><tr><td>变量</td><td>绑定已有工程数据点，核对真实路径、类型与变量名</td></tr><tr><td>触发</td><td>安排何时运行，不是设置一个按钮就能证明已经在节点执行</td></tr><tr><td>调试</td><td>检查已保存脚本的返回值、日志和错误</td></tr><tr><td>输出配置</td><td>定义生成哪些输出点及其类型、单位和空值行为</td></tr></tbody></table><p>在 **“变量”**点击 <strong>“插入数据点变量”</strong>，从已有点中选择，核对路径，再设置容易理解的变量名。不要只在代码里编造一个路径。</p><p>使用“代码模板”了解当前语言的读取方式，再按业务修改。AI 辅助时，明确要求引用本工程已有点，不将示例数据当成输入。</p><h2 id="_3-配置输出" tabindex="-1">3. 配置输出 <a class="header-anchor" href="#_3-配置输出" aria-label="Permalink to &quot;3. 配置输出&quot;">​</a></h2><p>打开 <strong>“输出配置”</strong>，核对输出 Key、显示名称、数据类型、单位和空值策略，保存后复制实际输出路径。</p><p>例如温度换算应返回数值，单位和页面显示要一致；不能把对象、数组、空值或字符串当作有效温度。</p><p>“跳过并保留旧值”不代表本次取得了新值。选择前确认旧值被保留时，页面和报警怎样识别质量与时间。</p><h2 id="_4-保存后再试运行" tabindex="-1">4. 保存后再试运行 <a class="header-anchor" href="#_4-保存后再试运行" aria-label="Permalink to &quot;4. 保存后再试运行&quot;">​</a></h2><p>完成修改，先点击 <strong>“保存”</strong>。出现“试运行用已保存版本，请先保存”时，不要继续以为调试的是最新草稿。</p><p>在“调试”准备参数并点击 <strong>“试运行”</strong>，查看“返回值”“日志”和“错误”。沙箱或语法检查不可用时先处理提示。</p><p><strong>试运行不会保存计算结果或写入输出数据点。</strong> 看到正确返回值，只说明这次调试的结果符合预期，不保证点位当前值更新或正式节点持续运行。</p><p>脚本涉及外部访问、写库等动作时，仍须先核对授权、目标和平台允许范围，不凭“试运行”三个字认定所有动作都可随意测试。</p><h2 id="_5-配置触发并启用" tabindex="-1">5. 配置触发并启用 <a class="header-anchor" href="#_5-配置触发并启用" aria-label="Permalink to &quot;5. 配置触发并启用&quot;">​</a></h2><p>在“触发”按用途选择当前可用的手动、周期、日历定时、数据点变化或条件触发，核对参数后保存。</p><p>“已启用”是配置状态，不是独立的运行健康证明。正式执行还需要相应工程内容部署、计算引擎、输入来源与触发条件均满足。</p><p>不要通过缩短周期、重复启用或循环触发制造很大的负载。正式运行前按业务频率和容量安排。</p><h2 id="_6-回到数据点与运行结果核对" tabindex="-1">6. 回到数据点与运行结果核对 <a class="header-anchor" href="#_6-回到数据点与运行结果核对" aria-label="Permalink to &quot;6. 回到数据点与运行结果核对&quot;">​</a></h2><p>进入 <strong>“数据中心” → “数据点”</strong>，按保存后的路径查找计算输出。查看来源，使用“打开计算单元”返回相同单元，再核对质量与时间。</p><p>需要用于页面时配置<a href="/induframe-docs/zh/guide/workspace-datapoints.html">工程角色调用权限</a>；需要用于报警时继续<a href="/induframe-docs/zh/guide/point-alarms.html">配置报警</a>。</p><p>下一步：<a href="/induframe-docs/zh/guide/data-flow-tutorial.html">SQL、计算与报警联动示例</a> · <a href="/induframe-docs/zh/guide/ai-data-review.html">AI 成果核对</a>。</p>',27)])])}const u=a(d,[["render",n]]);export{c as __pageData,u as default};
